<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import type { API } from '../../../shared/api'
import { isCancelled } from '../../../shared/console'
import MarkdownContent from '../../../shared/MarkdownContent.vue'
const props=defineProps<{api:API}>()
const rows=ref<any[]>([]),selected=ref<any>(null),hits=ref<any[]>([]),busy=ref(false),error=ref(''),notice=ref('')
const kind=ref('document'),title=ref(''),content=ref(''),authorship=ref('unknown'),query=ref(''),feedback=ref(''),outcome=ref('unknown')
const editing=ref(false),editTitle=ref(''),editContent=ref('')
const uploadFile=ref<File|null>(null),encoding=ref('auto')
const observations=ref<any[]>([]),consolidations=ref<any[]>([]),formStart=ref(0),formChars=ref(12000),formReceipt=ref<any>(null)
const formationLabels:Record<string,string>={approved:'核验通过',needs_assistance:'需要辅助核对',insufficient_sources:'等待不同来源积累',incomplete_source:'原文尚未完整处理',unknown_conditions:'适用条件不明',unknown_outcome:'验收结果尚未知',no_new_evidence:'没有新增支持',no_approved_observation:'无可用观察',review_required:'存在冲突，需辅助处理',noop:'暂不形成新结论',retired:'已停用',failed:'巩固阶段失败，观察已保留'}
const kinds:Record<string,string>={document:'文档',note:'笔记',task_result:'任务结果'},authors:Record<string,string>={self:'本人撰写',external:'第三方资料',unknown:'作者未知'}
const warningLabels:Record<string,string>={gb18030_auto_fallback:'按GB18030解码，请核对文字',images_not_recognized:'图片未识别',review_comments_excluded:'未导入批注',field_instructions_not_executed:'未执行动态域，保留已有显示文字',math_not_linearized:'公式未转换为文本'}
let alive=true
onUnmounted(()=>{alive=false})
async function run(task:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await task()}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
async function load(){const [value,memories]=await Promise.all([props.api.request('/library/sources'),props.api.request('/library/consolidations')]);if(alive){rows.value=value;consolidations.value=memories}}
async function choose(id:string){const [value,items]=await Promise.all([props.api.request('/library/sources/'+encodeURIComponent(id)),props.api.request('/library/sources/'+encodeURIComponent(id)+'/observations')]);if(alive){selected.value=value;observations.value=items;feedback.value='';outcome.value='unknown';editing.value=false;formStart.value=0;formReceipt.value=null}}
function edit(){if(!selected.value)return;editTitle.value=selected.value.revision.title;editContent.value=selected.value.revision.content;editing.value=true}
async function revise(){const item=selected.value;if(!item)return;await run(async()=>{await props.api.request('/library/sources/'+item.id+'/revisions',{expected_revision_id:item.revision.id,title:editTitle.value,content:editContent.value},'POST');if(alive){await choose(item.id);await load();hits.value=[];notice.value='修订已保存；旧版本保留，新版本需要重新提炼。'}})}
async function save(){await run(async()=>{const value=await props.api.request('/library/sources',{kind:kind.value,title:title.value,content:content.value,authorship:authorship.value},'POST');if(!alive)return;await choose(value.id);title.value='';content.value='';notice.value='已保存原始资料，未创建聊天消息或个人Claim。';await load()})}
function selectFile(event:Event){uploadFile.value=(event.target as HTMLInputElement).files?.[0]??null}
async function upload(){const file=uploadFile.value;if(!file)return;await run(async()=>{if(file.size>1048576)throw new Error('单文件上限1 MiB');const params=new URLSearchParams({filename:file.name,title:title.value,kind:kind.value,authorship:authorship.value,encoding:encoding.value});const value=await props.api.request('/library/import?'+params.toString(),file,'POST');if(alive){await choose(value.id);uploadFile.value=null;notice.value='文件已解析并保留原始字节与定位信息，未调用模型。';await load()}})}
async function search(){await run(async()=>{const value=await props.api.request('/library/search',{query:query.value},'POST');if(alive)hits.value=value})}
async function recordFeedback(){const item=selected.value;if(!item)return;await run(async()=>{await props.api.request('/library/sources/'+item.id+'/feedback',{expected_revision_id:item.revision.id,outcome:outcome.value,content:feedback.value},'POST');if(alive){await choose(item.id);hits.value=[];await load()}})}
async function distill(){const item=selected.value;if(!item)return;await run(async()=>{const value=await props.api.request('/library/sources/'+item.id+'/distill',{},'POST');if(alive){await choose(item.id);notice.value='本轮提炼：'+value.status}})}
async function formMemory(){const item=selected.value;if(!item)return;await run(async()=>{const value=await props.api.request('/library/sources/'+item.id+'/form',{start:formStart.value,max_chars:formChars.value,expected_revision_id:item.revision.id},'POST');if(alive){await choose(item.id);formReceipt.value=value;formStart.value=value.processed_span.end<value.processed_span.total?value.processed_span.end:0;await load();notice.value='本段形成'+value.observations.length+'条观察；'+(formationLabels[value.consolidation.status]??value.consolidation.status)+(value.consolidation.reason?'：'+value.consolidation.reason:'')}})}
async function consolidate(id:string){await run(async()=>{const result=await props.api.request('/library/observations/'+encodeURIComponent(id)+'/consolidate',{},'POST');if(alive){await load();notice.value=formationLabels[result.status]??result.status}})}
async function retire(memory:any){if(!window.confirm('停用这条自动巩固记忆？历史与原始资料保留，后续形成不会自动恢复这条记忆。'))return;await run(async()=>{await props.api.request('/library/consolidations/'+memory.root_id+'/retire',{expected_revision_id:memory.head_id,session_id:memory.memory?.group?.session_id??null},'POST');if(alive)await load()})}
async function retract(){const item=selected.value;if(!item||!window.confirm('撤回后退出检索，保留原始版本用于追溯。确认撤回？'))return;await run(async()=>{await props.api.request('/library/sources/'+item.id+'/retract',{},'POST');if(alive){selected.value=null;hits.value=[];await load()}})}
onMounted(()=>void run(load))
</script>
<template>
  <div class="library-page">
    <p class="library-intro">资料与个人事实分开：笔记、文档和任务结果直接进入当前账号的资料层；不自动变成“你喜欢什么”。任务经验结合明确反馈提炼，不自动发布可执行技能。</p>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <section class="panel"><h2>导入文本文件</h2><form @submit.prevent="upload"><label>文件<input type="file" accept=".txt,.text,.md,.markdown,.csv,.json,.jsonl,.docx" @change="selectFile"></label><label>文本编码<select v-model="encoding"><option value="auto">自动（UTF-8 / BOM / GB18030）</option><option value="utf-8">UTF-8</option><option value="utf-16">UTF-16（含BOM）</option><option value="gb18030">GB18030</option></select></label><p>使用下方选择的资料类型、作者归属和标题（标题为空则使用文件名）。支持现代Word .docx正文、表格及页眉页脚文字；旧.doc请先另存为.docx。单文件1 MiB、解析文字120000字符；不读取PDF或图片。</p><button :disabled="busy||!uploadFile">解析并保存文件（不调用模型）</button></form></section>
    <section class="panel"><h2>添加非对话资料</h2><form @submit.prevent="save">
      <div class="library-fields"><label>资料类型<select v-model="kind"><option value="document">文档</option><option value="note">笔记</option><option value="task_result">任务结果</option></select></label><label>作者归属<select v-model="authorship"><option value="unknown">未知</option><option value="self">本人撰写</option><option value="external">第三方资料</option></select></label></div>
      <label>标题<input v-model="title" maxlength="160" required placeholder="资料名称或任务名称"></label><label>正文<textarea v-model="content" rows="7" maxlength="120000" required placeholder="粘贴文本或 Markdown；任务结果请保留尝试、结果和可核对的验收信息。"></textarea></label>
      <button class="primary-button" :disabled="busy||!title.trim()||!content.trim()">保存资料</button><small>保存与检索不调用模型。形成每段最多两次阶段调用；达到不同来源门槛后，最多再作一次巩固与一次支持核验。每段12000字符，长文档逐段处理，不静默假装已处理全文。</small>
    </form></section>
    <section class="panel"><h2>检索资料与经验</h2><form class="library-search" @submit.prevent="search"><input v-model="query" maxlength="2000" required placeholder="输入资料主题"><button :disabled="busy||!query.trim()">检索</button></form>
      <article v-for="hit in hits" :key="hit.id" class="library-hit"><button class="text-button" @click="run(()=>choose(hit.source_id))">{{ hit.title }} →</button><p>{{ hit.citation }}</p><blockquote>{{ hit.quote }}</blockquote><p v-for="card in hit.knowledge_cards" :key="card.content">来源约束的观察：{{ card.content }}<br>适用范围：{{ card.applicability }}</p></article>
    </section>
    <div class="library-columns"><section class="panel"><h2>已保存资料（{{ rows.length }}）</h2><p v-if="!rows.length">暂无资料。可以直接添加笔记和文档，无需先发一条聊天消息。</p><button v-for="row in rows" :key="row.id" class="library-row" @click="run(()=>choose(row.id))"><strong>{{ row.title }}</strong><span>{{ kinds[row.kind] }} · {{ authors[row.authorship] }}</span></button></section>
      <section v-if="selected" class="panel"><h2>{{ selected.revision.title }}</h2><p>{{ kinds[selected.kind] }} · {{ authors[selected.authorship] }} · {{ selected.versions.length }} 个版本</p><p v-if="selected.file">文件：{{ selected.file.filename }} · {{ selected.file.format }} · {{ selected.file.encoding }} · {{ selected.file.anchors.length }} 处定位<span v-if="selected.file.warnings.length"> · 解析提示：{{ selected.file.warnings.map((w:string)=>warningLabels[w]??w).join(' / ') }}</span> · <a :href="'/api/library/sources/'+encodeURIComponent(selected.id)+'/file?revision_id='+encodeURIComponent(selected.revision.id)">下载原始文件</a></p><details><summary>查看解析原文</summary><pre v-if="selected.file&&!['md','markdown'].includes(selected.file.format)" class="library-raw">{{ selected.revision.content }}</pre><MarkdownContent v-else :content="selected.revision.content" /></details>
        <button :disabled="busy" @click="edit">修订资料</button><form v-if="editing" @submit.prevent="revise"><label>修订标题<input v-model="editTitle" maxlength="160" required></label><label>修订正文<textarea v-model="editContent" rows="7" maxlength="120000" required></textarea></label><button :disabled="busy||!editTitle.trim()||!editContent.trim()">保存新版本</button></form>
        <template v-if="selected.kind==='task_result'"><h3>验收反馈</h3><p v-if="selected.feedback">最近报告：{{ selected.feedback.outcome }} · {{ selected.feedback.content }}</p><p>流程完成不代表任务成功；请写明验收标准、实际结果或失败现象。</p><label>结果<select v-model="outcome"><option value="unknown">尚不确定</option><option value="success">报告成功</option><option value="failure">报告失败</option></select></label><label>反馈<textarea v-model="feedback" rows="3" maxlength="3000"></textarea></label><button :disabled="busy||!feedback.trim()" @click="recordFeedback">保存反馈</button></template>
        <h3>来源感知形成</h3><p>每段最多四条观察，LLM独立核验；不同来源默认达到三份才巩固。本人笔记、外部知识、任务经验分别归组，文件副本不增加支持数；条件或反馈不明时保留待辅助状态。</p><div class="library-fields"><label>本段起点（字符）<input v-model.number="formStart" type="number" min="0" :max="Math.max(0,Array.from(selected.revision.content).length-1)"></label><label>本段最大字符<input v-model.number="formChars" type="number" min="1" max="12000"></label></div><small>模型输入预算不足时可缩短当前段；不会自动付费处理其余段。</small><p v-if="formReceipt">已处理本段 {{ formReceipt.processed_span.start }}–{{ formReceipt.processed_span.end }} / {{ formReceipt.processed_span.total }} 字符；{{ formReceipt.source_complete?'当前版本已完整处理':'仍有未处理原文，不参与跨资料巩固' }}。</p>
        <div class="library-actions"><button :disabled="busy" @click="formMemory">形成本段并尝试巩固（调用模型）</button><button :disabled="busy" @click="retract">撤回资料</button></div>
        <details><summary>单条提炼入口</summary><p>只提炼一条来源观察，不执行跨资料巩固。</p><button :disabled="busy" @click="distill">单条提炼（调用模型）</button></details>
        <article v-for="observation in observations" :key="observation.id" class="library-hit"><strong>{{ observation.available?(formationLabels[observation.status]??observation.status):'来源/反馈已变化或观察不可用' }}</strong><p v-if="observation.content">{{ observation.content }}</p><p v-if="observation.group">{{ observation.group.lane }} · {{ observation.group.subject }} · {{ observation.group.topic }} · {{ observation.group.conditions||'默认条件' }}</p><button v-if="observation.available&&observation.source_complete" :disabled="busy" @click="consolidate(observation.id)">检查巩固（可能调用模型）</button></article>
        <article v-for="card in selected.cards" :key="card.id" class="library-hit"><strong>{{ card.available?'可用的来源观察':card.status==='approved'?'来源、时效或反馈变化，旧观察停用':'需要辅助核对' }}</strong><p>{{ card.content }}</p><p>适用范围：{{ card.applicability }}</p><blockquote>{{ card.quote }}</blockquote><blockquote v-if="card.subject_quote">主体证据：{{ card.subject_quote }}<br>{{ card.subject_citation }}</blockquote><blockquote v-if="card.feedback_quote">反馈：{{ card.feedback_quote }}</blockquote><details><summary>审核与准入原因</summary><pre>{{ card.verdict_json }}</pre></details></article>
      </section></div>
    <section class="panel"><h2>跨资料巩固记忆</h2><p>只用于资料范围内的有界归纳，不是本人Claim或通用技能；完整支持组任一必要来源失效即停用，有其他完整支持组才保留。</p><p v-if="!consolidations.length">暂无跨资料巩固记录。先形成来源观察，再积累不同资料。</p><article v-for="memory in consolidations" :key="memory.root_id" class="library-hit"><strong>{{ memory.status==='available'?'当前可用':memory.status==='retired'?'已主动停用':memory.status==='awaiting_sources'?'等待来源积累或巩固审核':'暂不可用：来源、反馈、时效、冲突或新证据待核验' }}</strong><template v-if="memory.memory"><p>{{ memory.memory.quote }}</p><p>适用范围：{{ memory.memory.applicability }}</p><details><summary>查看 {{ memory.memory.support.length }} 份必要证据</summary><blockquote v-for="support in memory.memory.support" :key="support.observation_id">{{ support.quote }}<br>{{ support.citation }}<template v-if="support.subject_quote"><br>主体证据：{{ support.subject_quote }}<br>{{ support.subject_citation }}</template><template v-if="support.feedback_quote"><br>反馈：{{ support.feedback_quote }}</template></blockquote></details><button :disabled="busy" @click="retire(memory)">停用这条巩固记忆</button></template><details><summary>最近版本记录（{{ memory.versions.length }}）</summary><p v-for="version in memory.versions" :key="version.id">{{ version.action }} · {{ formationLabels[version.status]??version.status }} · {{ version.assessment??'' }} {{ version.reason??'' }} · {{ version.created_at }}</p></details></article></section>
  </div>
</template>
<style scoped>
.library-raw,.library-hit pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:540px;overflow:auto;line-height:1.7;tab-size:4}
.library-page{display:grid;gap:20px}.library-intro{line-height:1.7;color:#607087}.library-fields,.library-search,.library-actions{display:flex;gap:12px;flex-wrap:wrap}.library-page form,.library-page label{display:grid;gap:8px}.library-page form{gap:14px}.library-page input,.library-page textarea,.library-page select{font:inherit;border:1px solid #dce3ed;border-radius:8px;padding:10px;width:100%;box-sizing:border-box}.library-page textarea{resize:vertical}.library-page small{display:block;color:#61718b;line-height:1.6}.library-columns{display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2fr);gap:20px}.library-row{display:grid;gap:8px;width:100%;padding:14px;text-align:left;border:0;border-bottom:1px solid #e8edf5;background:transparent;cursor:pointer}.library-row span{color:#6b7c94}.library-hit{margin-top:14px;padding:12px;border:1px solid #e5ebf5;border-radius:8px;overflow-wrap:anywhere}.library-hit blockquote{white-space:pre-wrap;border-left:3px solid #d2dcef;padding-left:12px;margin-left:0}.library-actions{margin-top:16px}.library-search{display:flex!important}.library-search input{flex:1;min-width:160px}@media(max-width:900px){.library-columns{grid-template-columns:1fr}}
</style>
